// SHAYEGAN prototype: renders the catalog from data/catalog.json.
// In production, catalog.json is generated by the Drive sync job
// (one folder per item, each with an info.json). No media files are
// served by this page; entries are metadata + official-source notes.

function posterSVG(seed, label) {
  const skies = [["#ff2975", "#8c1eff"], ["#ff4fd8", "#5a1fb8"], ["#ffd319", "#ff2975"], ["#8b3dff", "#ff2e88"]];
  const [c1, c2] = skies[seed % skies.length];
  const gid = "pg" + seed;
  const sunX = 90 + (seed * 53) % 220;
  const b = (x, w, h) => `<rect x="${x}" y="${150 - h}" width="${w}" height="${h}"/>`;
  const win = (x, y) => `<rect x="${x}" y="${y}" width="5" height="5"/>`;
  return `<svg class="poster" viewBox="0 0 400 150" role="img" aria-label="${label} artwork">
    <defs>
      <linearGradient id="${gid}" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stop-color="#0a0618"/><stop offset="0.6" stop-color="#1d0b3d"/><stop offset="1" stop-color="#3b0f4f"/>
      </linearGradient>
      <linearGradient id="${gid}s" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stop-color="#ffd319"/><stop offset="0.5" stop-color="${c1}"/><stop offset="1" stop-color="${c2}"/>
      </linearGradient>
      <clipPath id="${gid}c"><circle cx="${sunX}" cy="78" r="40"/></clipPath>
    </defs>
    <rect width="400" height="150" fill="url(#${gid})"/>
    <g fill="#ffffff"><circle cx="${30 + seed * 17 % 60}" cy="18" r="1.4"/><circle cx="${300 + seed * 13 % 70}" cy="14" r="1.2"/><circle cx="${180 + seed * 29 % 90}" cy="26" r="1"/></g>
    <g clip-path="url(#${gid}c)">
      <circle cx="${sunX}" cy="78" r="40" fill="url(#${gid}s)"/>
      <g fill="#0a0618"><rect x="${sunX - 45}" y="92" width="90" height="3"/><rect x="${sunX - 45}" y="101" width="90" height="4"/><rect x="${sunX - 45}" y="112" width="90" height="6"/></g>
    </g>
    <ellipse cx="${sunX}" cy="78" rx="74" ry="12" fill="none" stroke="${c1}" stroke-width="1.4" opacity=".7" transform="rotate(-10 ${sunX} 78)"/>
    <g fill="#120826">${b(8, 30, 46)}${b(46, 24, 64)}${b(78, 34, 38)}${b(288, 28, 58)}${b(324, 22, 42)}${b(354, 36, 68)}</g>
    <g fill="${c1}">${win(54, 96)}${win(54, 110)}${win(296, 102)}${win(362, 92)}${win(362, 108)}</g>
    <g fill="#ffd319">${win(16, 112)}${win(332, 116)}</g>
    <g stroke="${c1}" stroke-width="1" opacity=".5"><path d="M0 132 H400 M0 140 H400 M0 148 H400"/></g>
    <text x="14" y="144" fill="#f3eaff" font-family="monospace" font-size="13" letter-spacing="3">${label}</text>
  </svg>`;
}

function card(item, i) {
  const el = document.createElement("article");
  el.className = "card";
  // Downloads render ONLY for the creator's own works. Entries without
  // license "own-work" never get a download button, whatever URL they carry.
  const dl = (item.license === "own-work" && item.download_url)
    ? `<p><a class="btn primary" href="${item.download_url}" download>Download film</a></p>` : "";
  el.innerHTML = `${posterSVG(i + 1, item.title.toUpperCase())}
    <h3>${item.title} <span style="color:#9fb3c8">(${item.year})</span></h3>
    <p>${item.description}</p>
    <span class="badge">${item.genres.join(" · ")}</span>
    <p style="color:#9fb3c8;font-size:.9rem">${item.note}</p>${dl}`;
  return el;
}

async function load() {
  try {
    const res = await fetch("data/catalog.json");
    const data = await res.json();
    const mg = document.getElementById("movie-grid");
    const sg = document.getElementById("series-grid");
    data.movies.forEach((m, i) => mg.appendChild(card(m, i)));
    const ag = document.getElementById("ai-film-grid");
    (data.ai_films || []).forEach((f, i) => ag.appendChild(card(f, i + 4)));
    if ((data.ai_films || []).length) document.getElementById("ai-film-empty").remove();
    data.series.forEach((s, i) => sg.appendChild(card(s, i + 2)));
  } catch (e) {
    console.warn("catalog load failed", e);
  }
  try {
    const res = await fetch("data/news.json");
    const news = await res.json();
    const list = document.getElementById("news-list");
    if (!news.items.length) {
      list.innerHTML = `<div class="news-item">Feed pipeline ready. First curated drop pending — 10 stories a day across AI and gaming.</div>`;
    } else {
      news.items.forEach((n) => {
        const d = document.createElement("div");
        d.className = "news-item";
        const src = n.url ? ` · <a href="${n.url}" target="_blank" rel="noopener">${n.source || "Source"}</a>` : "";
        d.innerHTML = `<strong>${n.title}</strong><br><span style="color:#9fb3c8">${n.category} · ${n.date}${src}</span><p>${n.summary}</p>`;
        list.appendChild(d);
      });
    }
  } catch (e) {
    console.warn("news load failed", e);
  }
}
load();
